"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7969],{79443:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Builds a queue. `name` and `size` are required; see the configuration table\\non [Matchmaker] for the rest.\\n\\nConfiguration problems throw rather than returning a `Result`, since they\\ncannot be recovered from at runtime.","params":[{"name":"config","desc":"","lua_type":"MatchmakerConfig"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","errors":[{"lua_type":"\\"Muster: ...\\"","desc":"Reported at the call site, naming the offending field."}],"source":{"line":167,"path":"src/Matchmaker.luau"}},{"name":"enqueue","desc":"Queues one player as a one-member ticket.\\n\\nOn a rated queue, `options.rating` is required unless `rating.default` is\\nconfigured; on an unrated queue, supplying one throws.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"},{"name":"options","desc":"","lua_type":"EnqueueOptions?"}],"returns":[{"desc":"","lua_type":"Result<Ticket>"}],"function_type":"static","errors":[{"lua_type":"\\"Muster: queue \\\\\\"<name>\\\\\\" is rated but no rating was given\\"","desc":"No rating and no default."},{"lua_type":"\\"Muster: queue \\\\\\"<name>\\\\\\" is unrated, so `rating` cannot be supplied\\"","desc":"Rating passed to an unrated queue."}],"source":{"line":286,"path":"src/Matchmaker.luau"}},{"name":"enqueueGroup","desc":"Queues a set of players as one ticket. The group is never split across\\nmatches and is matched at its aggregate rating.\\n\\nTakes userIds directly and does not involve [Party]. The first userId becomes\\nthe ticket\'s leader, and is the only one who may cancel or acknowledge it.\\n\\n```lua\\nqueue:enqueueGroup({ leaderId, friendId }, { ratings = ratings })\\n```\\n\\nGroups larger than `size.max` are rejected with `InvalidPartySize`, and a\\nrepeated userId with `DuplicateMember`.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userIds","desc":"","lua_type":"{ number }"},{"name":"options","desc":"","lua_type":"GroupOptions?"}],"returns":[{"desc":"","lua_type":"Result<Ticket>"}],"function_type":"static","source":{"line":324,"path":"src/Matchmaker.luau"}},{"name":"enqueueParty","desc":"Queues a [Party] by id. Only the party\'s leader may call this.\\n\\nThe party\'s membership is locked for the lifetime of the ticket: invites,\\nkicks, leaves, leadership transfers and disbanding all return `PartyLocked`\\nuntil the ticket matches, is cancelled, or expires.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"options","desc":"`ratings` is keyed by userId.","lua_type":"GroupOptions?"}],"returns":[{"desc":"","lua_type":"Result<Ticket>"}],"function_type":"static","source":{"line":359,"path":"src/Matchmaker.luau"}},{"name":"cancel","desc":"Cancels a ticket.\\n\\nOnly the ticket\'s leader may cancel it, and only while its state is\\n`Queued`. A ticket already claimed for a match returns `NotQueued`.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Result<true>"}],"function_type":"static","source":{"line":436,"path":"src/Matchmaker.luau"}},{"name":"cancelForUser","desc":"Cancels whatever ticket a user currently holds, if any.\\n\\nUnlike [Matchmaker:cancel], this looks the ticket up and cancels it as its\\nleader, so it works for any member of a group. Connected to\\n`Players.PlayerRemoving` unless `autoCancelOnLeave` is disabled.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"True if a ticket was cancelled, false if the user had none queued.","lua_type":"Result<boolean>"}],"function_type":"static","source":{"line":450,"path":"src/Matchmaker.luau"}},{"name":"getTicket","desc":"The ticket a user currently holds, or `nil`.\\n\\nTickets are exclusive across every queue sharing a namespace, so this returns\\na ticket even if the user queued somewhere else.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Result<Ticket?>"}],"function_type":"static","source":{"line":476,"path":"src/Matchmaker.luau"}},{"name":"getStatus","desc":"The state of a ticket: `Queued`, `Claiming`, `Matched`, `Cancelled`, or\\n`Expired`. A `Matched` status carries the envelope.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Result<QueueStatus<T>>"}],"function_type":"static","source":{"line":487,"path":"src/Matchmaker.luau"}},{"name":"getMatch","desc":"Reads a committed match by id, or `nil` if there is no ready match under that\\nid. Matches remain readable for `matchExpiration` (300 s), which covers a\\nplayer who rejoined on another server and needs the envelope again.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Result<MatchEnvelope<T>?>"}],"function_type":"static","source":{"line":499,"path":"src/Matchmaker.luau"}},{"name":"acknowledge","desc":"Releases a matched ticket\'s players so they may queue again, and unlocks its\\nparty.\\n\\nThis happens automatically on delivery unless `manualAcknowledge` is set.\\nEnable that setting to hold the reservation until you have confirmed whatever\\nfollows the match, such as a teleport. A failure then leaves the players free\\nto re-queue rather than locked out until their reservation expires.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Result<MatchEnvelope<T>>"}],"function_type":"static","source":{"line":515,"path":"src/Matchmaker.luau"}},{"name":"step","desc":"Runs one worker pass: ticket upkeep, lane acquisition, then a scan of each\\nheld lane.\\n\\nThe worker thread calls this on a loop. Calling it directly advances the\\nsystem one step, which is how the test suite drives it without yielding.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":528,"path":"src/Matchmaker.luau"}},{"name":"start","desc":"Starts the worker thread and subscribes for cross-server delivery. Called by\\nthe constructor unless `autoStart` is disabled. Calling it twice does\\nnothing.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":539,"path":"src/Matchmaker.luau"}},{"name":"stop","desc":"Stops the worker and releases every lane lease this server holds, so another\\nserver can take them immediately instead of waiting out the 15-second\\ntimeout. Suitable for `game:BindToClose`.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":550,"path":"src/Matchmaker.luau"}},{"name":"destroy","desc":"Calls [Matchmaker:stop], disconnects the `PlayerRemoving` connection, and\\ndrops every signal handler.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":560,"path":"src/Matchmaker.luau"}},{"name":"health","desc":"A snapshot of this server\'s view of the queue, for logging or a debug\\ncommand.\\n\\n| Field | Meaning |\\n| --- | --- |\\n| `localTickets` | Tickets this server enqueued and is still tracking. |\\n| `ownedLanes` | Lane leases this server currently holds. |\\n| `laneMode` | `\\"auto\\"` or `\\"fixed\\"`. |\\n| `laneCount` | Lanes the default partition is sharded into. |\\n| `laneChanges` | Resizes this server has applied. |\\n| `throttled` | True once 1% of requests have come back throttled. |\\n| `broadcastHealthy` | False while message delivery looks unreliable. |\\n| `broadcastsSent` / `broadcastsReceived` | Message counts since start. |\\n| `requests` | Per-structure successes, failures, throttles and mean latency. |\\n\\nValues are local to this server, not fleet-wide.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":592,"path":"src/Matchmaker.luau"}}],"properties":[{"name":"matched","desc":"Fires on every server holding at least one of the matched players. Does not\\nfire on a server holding none of them.","lua_type":"Signal<MatchEnvelope<T>>","source":{"line":125,"path":"src/Matchmaker.luau"}},{"name":"aborted","desc":"Fires when a match that had already claimed its tickets failed to commit. Its\\nplayers return to the queue. See [AbortReason].","lua_type":"Signal<AbortContext>","source":{"line":133,"path":"src/Matchmaker.luau"}},{"name":"queued","desc":"Fires on this server when a ticket is successfully enqueued here.","lua_type":"Signal<Ticket>","source":{"line":140,"path":"src/Matchmaker.luau"}},{"name":"cancelled","desc":"Fires on this server when a ticket it was tracking is cancelled.","lua_type":"Signal<Ticket>","source":{"line":147,"path":"src/Matchmaker.luau"}},{"name":"parties","desc":"Cross-server parties sharing this queue\'s store. Built on first access and\\nwrites nothing until used; see [Party].","lua_type":"Party","source":{"line":155,"path":"src/Matchmaker.luau"}}],"types":[],"name":"Matchmaker","desc":"A single queue. Construct one per game mode.\\n\\n```lua\\nlocal duels = Muster.new({ name = \\"duels\\", size = 2 })\\n\\nduels.matched:connect(function(match)\\n\\tfor _, member in match.members do\\n\\t\\tprint(member.userId, \\"->\\", match.matchId)\\n\\tend\\nend)\\n\\nduels:enqueue(player.UserId)\\n```\\n\\nConstructing a queue starts its worker thread, subscribes it for cross-server\\ndelivery, and connects `Players.PlayerRemoving` to cancel tickets. Each of\\nthose can be disabled with `autoStart`, `broadcast`, and `autoCancelOnLeave`.\\n\\n### Configuration\\n\\n`name` and `size` are required. Everything else has a default.\\n\\n| Field | Type | Default | Effect |\\n| --- | --- | --- | --- |\\n| `name` | `string` | required | Namespaces this queue\'s keys. Max 16 characters, alphanumeric plus `_` and `-`. |\\n| `size` | `number \\\\| SizeConfig` | required | `6` is shorthand for `{ min = 6, target = 6, max = 6 }`. |\\n| `rating` | `RatingConfig?` | `nil` | Present makes the queue rated. See [RatingConfig]. |\\n| `fallbackAfter` | `number` | `10` | Seconds before a below-`target` group is accepted. |\\n| `finalize` | `Finalizer<T>?` | `nil` | Runs once per match; its return value becomes `match.data`. |\\n| `finalizeTimeout` | `number` | `5` | Seconds. Must not exceed 15. |\\n| `onAbort` | `AbortHandler?` | `nil` | Called when a match fails after its hook ran. Requires `finalize`. |\\n| `partitionKey` | `function?` | `nil` | Returns a partition name per ticket. Partitions never match each other. |\\n| `lanes` | `\\"auto\\" \\\\| number` | `\\"auto\\"` | Pinning a number disables runtime scaling. See [LaneScaler]. |\\n| `broadcast` | `boolean` | `true` | Publish match notifications over MessagingService. |\\n| `autoStart` | `boolean` | `true` | Start the worker thread on construction. |\\n| `autoCancelOnLeave` | `boolean` | `true` | Cancel a player\'s ticket when they leave. |\\n| `manualAcknowledge` | `boolean` | `false` | Require [Matchmaker:acknowledge] to release matched players. |\\n| `ticketExpiration` | `number` | `180` | Seconds a ticket survives without a heartbeat. Minimum 30. |\\n| `maxMetadataBytes` | `number` | `1024` | Per-ticket metadata budget. |\\n| `maxMatchDataBytes` | `number` | `4096` | Budget for the finalizer\'s return value. |\\n| `namespace` | `string` | `\\"mu\\"` | Change to run independent deployments in one universe. |\\n\\nThese accept injected implementations, primarily for tests: `store`,\\n`messaging`, `players`, `matcher`, `layout`, `logger`, `metrics`, `clock`,\\n`monotonic`, `random`, `sleep`, `spawn`, `id`, `serverId`.\\n\\n### Delivery\\n\\n`matched` fires on every server holding at least one of the matched players.\\nA server holding none of them does not receive the event, so a handler can\\nassume it has someone to act on.\\n\\nMatches are written to MemoryStore before being announced, so delivery does\\nnot depend on MessagingService. Typical latency is under 200 ms; if a message\\nis dropped, a poll finds the match within `pollIntervalMax` (30 s). If\\nMessagingService is unavailable the poll cap tightens to 5 s automatically.","source":{"line":63,"path":"src/Matchmaker.luau"}}')}}]);